input.sparql:
SELECT DISTINCT ?point ?label
{
  ?p a brick:OccupancySensor .
  OPTIONAL{ ?p rdfs:label ?label }
  ?p ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?point .
}
LIMIT 50

SELECT DISTINCT ?a
{
  ?s a ?a .
  FILTER(?a != brick:Zone)
}
LIMIT 200

SELECT DISTINCT ?o
{
  ?p a brick:Occupancy_Sensor .
  ?p ?s ?o .
}
LIMIT 40

SELECT ?room ?rlabel ?zone ?zlabel
{
  ?room a brick:Room .
  OPTIONAL{ ?room rdfs:label ?rlabel }
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?zlabel .
  ?room brick:hasLocation ?zone .
  FILTER(?zlabel IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
}
LIMIT 40

SELECT DISTINCT ?z
{
  ?z a brick:HVAC_Zone .
}
LIMIT 40

SELECT DISTINCT ?z ?s ?o
{
  ?z a brick:HVAC_Zone .
  ?z ?s ?o .
}
LIMIT 60

SELECT ?zlabel ?zuri ?occ ?occseries
{
  ?zone a brick:HVAC_Zone ; rdfs:label ?zlabel ; brick:hasPoint ?occ .
  ?occ a brick:Occupancy_Sensor .
  OPTIONAL{ ?occ ref:hasExternalReference ?e ; ref:hasTimeseriesId ?occseries }
  FILTER(?zlabel IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
}

SELECT DISTINCT ?room ?occ ?seriesId
{
  ?room a brick:Room ; brick:hasPoint ?occ .
  ?occ a brick:Occupancy_Sensor ; ref:hasExternalReference ?e ; ref:hasTimeseriesId ?seriesId .
}
ORDER BY ?room

PREFIX brick: <http://brickschema.org/brick#>
SELECT ?zlabel ?part
{
  ?zone a brick:HVAC_Zone ; rdfs:label ?zlabel ; brick:hasPart ?part .
}
ORDER BY ?zlabel ?part

PREFIX brick: <http://brickschema.org/brick#>
SELECT ?zlabel ?part
{
  ?zone a brick:HVAC_Zone ; rdfs:label ?zlabel ; brick:hasPart ?part .
  FILTER(?zlabel IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
}

SELECT ?zlabel ?part
{
  ?zone a <http://brickschema.org/schema/Brick/HVAC_Zone> ; rdfs:label ?zlabel ; <http://brickschema.org/schema/Brick/hasPart> ?part .
  FILTER(?zlabel IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
}
ORDER BY ?zlabel ?part

SELECT DISTINCT ?p
{
  ?s <http://buildgraph.org/BG_medium_office_2004_0000#Room_F3_R009.Occupancy_Sensor> .
}

SELECT ?p ?o
{
  <http://buildgraph.org/BG_medium_office_2004_0000#Room_F3_R009.Occupancy_Sensor> ?p ?o .
}
LIMIT 30

